async def act(page):
    """
    Navigate to the Sample Page, find the 'Archives' section, and click the second-most-recent archive link.

    Implementation notes:
    - Use accessibility-role-centric selectors only.
    - Await locator.count() before using .nth().
    - Keep the final archive-link click as the last action because it may navigate away.
    """

    # 1) Navigate to the Sample Page where Archives is likely present
    await page.goto("/?page_id=2")

    # 2) Attempt to dismiss an obvious popup if present by clicking common close buttons
    close_candidates = ["×", "✕", "X", "Close", "close", "Dismiss", "dismiss"]
    dismissed = False
    for name in close_candidates:
        try:
            btn = page.get_by_role("button", name=name)
            if await btn.count() > 0:
                try:
                    await btn.first.click()
                except Exception:
                    # ignore individual click failures and continue trying other candidates
                    pass
                # give the page a moment to update
                try:
                    await page.wait_for_timeout(250)
                except Exception:
                    pass
                dismissed = True
                break
        except Exception:
            # creating locator may fail for some names; continue
            continue

    # 3) If not dismissed by named buttons, scan a small set of visible buttons for aria-label/inner text suggesting a close control
    if not dismissed:
        try:
            all_buttons = page.get_by_role("button")
            btn_count = await all_buttons.count()
            n = min(btn_count, 20)
            for i in range(n):
                try:
                    aria = (await all_buttons.nth(i).get_attribute("aria-label")) or ""
                    text = ""
                    try:
                        text = (await all_buttons.nth(i).inner_text()) or ""
                    except Exception:
                        text = ""
                    combined = (aria + " " + text).strip().lower()
                    if not combined:
                        continue
                    if ("close" in combined) or ("dismiss" in combined) or ("×" in combined) or ("✕" in combined):
                        try:
                            await all_buttons.nth(i).click()
                        except Exception:
                            pass
                        try:
                            await page.wait_for_timeout(250)
                        except Exception:
                            pass
                        dismissed = True
                        break
                except Exception:
                    continue
        except Exception:
            # nothing to do here
            pass

    # 4) Final fallback: press Escape to try to close any modal/popups
    if not dismissed:
        try:
            await page.keyboard.press("Escape")
            try:
                await page.wait_for_timeout(250)
            except Exception:
                pass
        except Exception:
            pass

    # 5) Locate the 'Archives' heading (exact match first)
    archives_heading = page.get_by_role("heading", name="Archives")
    if await archives_heading.count() == 0:
        # fallback: scan headings for substring 'archives' (case-insensitive)
        all_headings = page.get_by_role("heading")
        try:
            hcount = await all_headings.count()
        except Exception:
            hcount = 0
        found = False
        for i in range(hcount):
            try:
                txt = (await all_headings.nth(i).inner_text()) or ""
                if "archives" in txt.lower():
                    archives_heading = all_headings.nth(i)
                    found = True
                    break
            except Exception:
                continue
        if not found:
            raise RuntimeError("Could not find a heading named 'Archives' on the Sample Page")

    # 6) Find a semantic container that contains the Archives heading using .filter(has=...)
    container = None
    roles_to_probe = (
        "complementary",
        "aside",
        "region",
        "navigation",
        "section",
        "footer",
        "group",
        "list",
        "article",
        "main",
    )
    for role in roles_to_probe:
        try:
            candidates = page.get_by_role(role)
            if await candidates.count() == 0:
                continue
            matches = candidates.filter(has=archives_heading)
            if await matches.count() > 0:
                container = matches.nth(0)
                break
        except Exception:
            continue

    # 7) If container not found via filter, try to find a container role with visible name 'Archives' directly
    if container is None:
        for role in ("complementary", "aside", "region", "navigation", "section", "list", "group"):
            try:
                candidate = page.get_by_role(role, name="Archives")
                if await candidate.count() > 0:
                    container = candidate.nth(0)
                    break
            except Exception:
                continue

    if container is None:
        raise RuntimeError("Could not find a container that contains the 'Archives' heading on the Sample Page")

    # 8) Within the container, gather role='link' children and click the second-most-recent (index 1)
    links = container.get_by_role("link")
    try:
        links_count = await links.count()
    except Exception:
        links_count = 0
    if links_count < 2:
        raise RuntimeError(f"Expected at least 2 archive links under 'Archives', found {links_count}")

    # Final action: click the second-most-recent archive link (this may navigate away)
    await links.nth(1).click()

